import os
from typing import Dict, Any, List
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import DocumentAnalysisFeature

def get_field_string(field: Any) -> str:
    if hasattr(field, 'valueString') and field.valueString is not None:
        return field.valueString
    elif hasattr(field, 'content'):
        return field.content
    return ""

def get_field_number(field: Any) -> float:
    if hasattr(field, 'valueNumber') and field.valueNumber is not None:
        return float(field.valueNumber)
    elif hasattr(field, 'content'):
        try:
            cleaned = field.content.replace('$', '').replace(',', '').replace('(', '').replace(')', '').strip()
            return float(cleaned)
        except (ValueError, AttributeError):
            pass
    return 0.0

def extract_normalized_expenses(document_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-expense", document=f.read())

    result = poller.result()
    if not result.documents:
        return {}

    fields = result.documents[0].fields

    normalized: Dict[str, Any] = {
        "vendor_name": get_field_string(fields.get("VendorName")) or get_field_string(fields.get("MerchantName")),
        "invoice_id": get_field_string(fields.get("InvoiceId")),
        "invoice_date": get_field_string(fields.get("InvoiceDate")) or get_field_string(fields.get("DocumentDate")),
        "due_date": get_field_string(fields.get("DueDate")),
        "customer_name": get_field_string(fields.get("CustomerName")),
        "customer_id": get_field_string(fields.get("CustomerId")),
        "subtotal": get_field_number(fields.get("Subtotal")),
        "tax": get_field_number(fields.get("Tax")),
        "total": get_field_number(fields.get("Total")),
        "line_items": []
    }

    items_field = fields.get("Items")
    if items_field and hasattr(items_field, 'value') and items_field.value:
        for item in items_field.value:
            line_item = {
                "description": get_field_string(item.get("Description")),
                "quantity": get_field_number(item.get("Quantity")),
                "unit_price": get_field_number(item.get("UnitPrice")),
                "total": get_field_number(item.get("Total"))
            }
            normalized["line_items"].append(line_item)

    return normalized
